/**
 * @clawnify/db — dual-binding SQLite adapter for Clawnify apps.
 *
 * Two ways to use the package:
 *
 *   1. **Typed Drizzle queries** (preferred for new apps):
 *
 *      import { getDB } from "@clawnify/db";
 *      import * as schema from "./schema";   // your Drizzle table defs
 *
 *      const db = getDB(c.env, { schema });
 *      const rows = await db.select().from(schema.users).where(eq(...));
 *      await db.insert(schema.users).values({ name, prefs });
 *
 *      JSON columns (`text(col, { mode: 'json' })`) serialize automatically;
 *      no `JSON.stringify` at call sites.
 *
 *   2. **Raw SQL** (escape hatch for schema-as-data patterns like
 *      open-cms's per-collection tables, which Drizzle can't model
 *      because the schema is defined by runtime rows):
 *
 *      import { initDB, query, get, run, json } from "@clawnify/db";
 *      initDB(c.env);
 *      await run("INSERT INTO ct (uid, info) VALUES (?, ?)",
 *                [uid, json(infoObject)]);
 *
 *      assertBindable() runs implicitly inside run/get/query — passing a
 *      raw object instead of `json(...)` throws a clear TypeError with
 *      the offending param index.
 *
 * Auto-detects the storage backend at runtime:
 *
 *   - **Production (Workers for Platforms)**: `env.DB` is a real
 *     `D1Database`. Calls go through D1's HTTP API.
 *
 *   - **Preview (Dynamic Workers + DO Facet)**: `env.STORAGE` is a
 *     capability-wrapped RPC binding handed in by the Clawnify
 *     supervisor. Calls go through the in-process Facet SQLite
 *     (µs latency, ~10x faster than D1). Drizzle reaches it via
 *     `drizzle-orm/sqlite-proxy` with a callback that wraps the
 *     binding's `query(sql, params)` RPC.
 *
 * Also owns the `StorageBinding` RPC contract. The Clawnify supervisor
 * implements this interface and hands it to dynamic isolates via
 * `ctx.exports.Storage({ props })`.
 */

import { drizzle as drizzleD1, type DrizzleD1Database } from "drizzle-orm/d1";
import { drizzle as drizzleProxy, type SqliteRemoteDatabase } from "drizzle-orm/sqlite-proxy";

/**
 * Result of a SQL operation against an app's storage Facet.
 *
 * `rows` is the result set (empty for write-only statements).
 * `meta` carries D1/SQLite-style row counts so write statements can
 * report `changes` and `lastInsertRowid`. Optional because not every
 * implementation surfaces it.
 */
export interface StorageResult {
  rows: Record<string, unknown>[];
  /** Positional values preserve duplicate SELECT names and column order. */
  rawRows?: unknown[][];
  meta?: StorageMeta;
}

export interface StorageMeta {
  changes?: number;
  last_row_id?: number;
}

/**
 * The minimal contract the supervisor's `Storage` `WorkerEntrypoint`
 * exposes to dynamic isolates. Mirrors D1's batch-style query API in
 * spirit but collapses prepare/bind/all into a single RPC call.
 */
export interface StorageBinding {
  query(sql: string, params?: unknown[], rowMode?: "raw"): Promise<StorageResult>;
}

export interface DBEnv {
  DB?: D1Database;
  STORAGE?: StorageBinding;
}

export interface RunResult {
  changes: number;
  lastInsertRowid: number;
}

interface DbImpl {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
  get<T>(sql: string, params: unknown[]): Promise<T | undefined>;
  run(sql: string, params: unknown[]): Promise<RunResult>;
}

let _impl: DbImpl | null = null;

/**
 * Initializes the adapter. Call once per request (or once per Worker
 * instance) before any query/get/run call.
 *
 * Accepts either:
 *   - The whole env object — preferred; the adapter picks `env.DB` or
 *     `env.STORAGE`.
 *   - A raw `D1Database` — legacy signature so today's `initDB(c.env.DB)`
 *     call sites keep working unchanged.
 */
export function initDB(arg: D1Database | DBEnv): void {
  if (arg && typeof (arg as D1Database).prepare === "function") {
    _impl = d1Impl(arg as D1Database);
    return;
  }
  const env = arg as DBEnv;
  if (env.DB && typeof env.DB.prepare === "function") {
    _impl = d1Impl(env.DB);
    return;
  }
  if (env.STORAGE && typeof env.STORAGE.query === "function") {
    _impl = storageImpl(env.STORAGE);
    return;
  }
  throw new Error(
    "@clawnify/db: initDB called without a usable binding (need env.DB or env.STORAGE)",
  );
}

function ensure(): DbImpl {
  if (!_impl) {
    throw new Error("@clawnify/db: not initialized — call initDB(env) first");
  }
  return _impl;
}

export async function query<T = Record<string, unknown>>(
  sql: string,
  params: unknown[] = [],
): Promise<T[]> {
  assertBindable(params);
  return ensure().query<T>(sql, params);
}

export async function get<T = Record<string, unknown>>(
  sql: string,
  params: unknown[] = [],
): Promise<T | undefined> {
  assertBindable(params);
  return ensure().get<T>(sql, params);
}

export async function run(
  sql: string,
  params: unknown[] = [],
): Promise<RunResult> {
  assertBindable(params);
  return ensure().run(sql, params);
}

/**
 * Convenience helper for JSON columns. Equivalent to `JSON.stringify(value)`
 * but reads as intent: `run("INSERT ... VALUES (?, ?)", [uid, json(info)])`.
 * Returns null for `null`/`undefined` so the column stores NULL instead of
 * the literal strings "null"/"undefined".
 */
export function json<T = unknown>(value: T): string | null {
  if (value === null || value === undefined) return null;
  return JSON.stringify(value);
}

/**
 * Throws if any element of `params` is a value SQLite/D1 can't bind. The
 * native error messages are notoriously unhelpful here:
 *   - D1:    `D1_TYPE_ERROR: Type 'object' not supported for value '<some
 *            string>'`  (often pointing at the wrong param)
 *   - SQLite (via Facet): `Wrong number of parameter bindings for SQL query`
 *            when the binding is silently dropped
 *
 * Catching at the bindings boundary surfaces the real culprit with the
 * exact index, before the SQL ever leaves the worker.
 *
 * Bindable types: string, number, boolean, bigint, null, undefined,
 * Uint8Array, ArrayBuffer. Everything else (plain objects, arrays, Date,
 * etc.) needs explicit serialization — use `json(value)` for JSON columns.
 */
export function assertBindable(params: unknown[]): void {
  for (let i = 0; i < params.length; i++) {
    const v = params[i];
    if (v === null || v === undefined) continue;
    const t = typeof v;
    if (t === "string" || t === "number" || t === "boolean" || t === "bigint") {
      continue;
    }
    if (v instanceof Uint8Array || v instanceof ArrayBuffer) continue;
    const preview = (() => {
      try {
        const s = JSON.stringify(v);
        return s.length > 80 ? s.slice(0, 77) + "..." : s;
      } catch {
        return String(v);
      }
    })();
    throw new TypeError(
      `@clawnify/db: param [${i}] is ${t} — D1/SQLite only binds scalars. ` +
        `If this is a JSON column, wrap with json(value). Got: ${preview}`,
    );
  }
}

/**
 * Returns a typed Drizzle instance bound to whichever backend `env`
 * exposes (D1 via `env.DB`, Facet via `env.STORAGE`). Pass `schema`
 * so the query builder is typed against your table definitions.
 *
 * The return type is the union of `DrizzleD1Database<TSchema>` and
 * `SqliteRemoteDatabase<TSchema>` — both share a common base, so
 * `.select()`, `.insert()`, `.update()`, `.delete()` work uniformly.
 * Backend-specific surface (D1's `.batch()`, etc.) narrows on use.
 *
 * Transactions: D1 supports `db.batch([...])` for atomic batches.
 * The Facet path runs each statement individually (sqlite-proxy's
 * remote transaction support is limited). Architect schema and
 * queries to be idempotent on the Facet path until we add a custom
 * transactional bridge.
 */
export function getDB<TSchema extends Record<string, unknown> = Record<string, never>>(
  env: DBEnv,
  options?: { schema?: TSchema; logger?: boolean },
): DrizzleD1Database<TSchema> | SqliteRemoteDatabase<TSchema> {
  if (env.DB && typeof env.DB.prepare === "function") {
    return drizzleD1(env.DB, {
      schema: options?.schema,
      logger: options?.logger,
    });
  }
  if (env.STORAGE && typeof env.STORAGE.query === "function") {
    const storage = env.STORAGE;
    return drizzleProxy(
      async (sql, params, method) => {
        assertBindable(params);
        const result = await storage.query(sql, params, "raw");
        // drizzle-orm/sqlite-proxy expects positional row arrays:
        //   - method 'get'  → { rows: unknown[] }  (single row, positional)
        //   - method 'all'  → { rows: unknown[][] } (array of positional rows)
        //   - method 'run'  → { rows: [] }
        //   - method 'values' → { rows: unknown[][] }
        // Object rows lose duplicate names in joins and reorder integer-like
        // column names. New supervisors return the cursor's positional values.
        // Keep compatibility with older supervisors for existing simple queries.
        const rows = result.rawRows ?? result.rows.map(row => Object.values(row));
        if (method === "get") {
          return { rows: rows[0] ?? [] };
        }
        return { rows };
      },
      {
        schema: options?.schema,
        logger: options?.logger,
      },
    );
  }
  throw new Error(
    "@clawnify/db: getDB called without a usable binding (need env.DB or env.STORAGE)",
  );
}

function d1Impl(db: D1Database): DbImpl {
  return {
    async query<T>(sql: string, params: unknown[]) {
      const { results } = await db.prepare(sql).bind(...params).all<T>();
      return results ?? [];
    },
    async get<T>(sql: string, params: unknown[]) {
      const row = await db.prepare(sql).bind(...params).first<T>();
      return row ?? undefined;
    },
    async run(sql: string, params: unknown[]) {
      const r = await db.prepare(sql).bind(...params).run();
      return {
        changes: r.meta?.changes ?? 0,
        lastInsertRowid: Number(r.meta?.last_row_id ?? 0),
      };
    },
  };
}

function storageImpl(s: StorageBinding): DbImpl {
  return {
    async query<T>(sql: string, params: unknown[]) {
      const result = await s.query(sql, params);
      return (result.rows as T[]) ?? [];
    },
    async get<T>(sql: string, params: unknown[]) {
      const result = await s.query(sql, params);
      const rows = result.rows as T[];
      return rows[0] ?? undefined;
    },
    async run(sql: string, params: unknown[]) {
      const result = await s.query(sql, params);
      return {
        changes: result.meta?.changes ?? 0,
        lastInsertRowid: Number(result.meta?.last_row_id ?? 0),
      };
    },
  };
}

// ── Drizzle convenience re-exports ────────────────────────────────────
//
// Most apps that use `getDB` also reach for Drizzle's operators (eq,
// and, sql, etc.) and the SQLite schema DSL (sqliteTable, text,
// integer, ...). Re-exporting the common surface here means a typical
// app needs only one import line:
//
//   import {
//     getDB, eq, and, sql, sqliteTable, text, integer
//   } from "@clawnify/db";
//
// `drizzle-orm` stays a peerDependency — these re-exports are
// convenience, not a vendored copy. Apps with exotic Drizzle needs
// (the long tail) keep importing from `drizzle-orm` directly.

// Operators + SQL builder
export {
  eq, ne, gt, gte, lt, lte,
  isNull, isNotNull,
  and, or, not,
  inArray, notInArray,
  between, notBetween,
  like, notLike, ilike, notIlike,
  asc, desc,
  count, countDistinct, sum, sumDistinct, avg, avgDistinct, min, max,
  exists, notExists,
  sql,
  relations,
} from "drizzle-orm";

// SQLite schema DSL
export {
  sqliteTable, sqliteView,
  text, integer, real, blob, numeric,
  primaryKey, foreignKey, unique, uniqueIndex,
  index,
  check,
  customType,
} from "drizzle-orm/sqlite-core";
