/**
 * @clawnify/app — the standard Clawnify app skeleton in one call.
 *
 * `createApp(opts)` returns a fully-wired OpenAPIHono with every always-required,
 * cross-cutting concern pre-baked, so an app's server file is just imports +
 * routes + `export default app`:
 *
 *   import { createApp, createRoute, z } from "@clawnify/app";
 *   const app = createApp<Env>({ title: "CRM App", version: "1.0.0" });
 *   app.openapi(listContacts, handler);
 *   export default app;
 *
 * What it bakes in — the boilerplate every app used to re-write in its server
 * file, and could forget:
 *   • OpenAPIHono construction (typed to your Env).
 *   • Database init — `initDB(c.env)` middleware on every request. @clawnify/db
 *     auto-detects the D1 binding (production WfP) or the Storage capability
 *     binding (Dynamic Workers preview), so handlers can query immediately.
 *   • API discovery — `mountDiscovery` serves GET /api/openapi.json (the machine
 *     contract) and GET /llms.txt (the lean agent index), generated from the
 *     live routes so they can't drift.
 *   • Identity — `user(c)` / `orgId(c)` / `caller(c)` read the platform-injected
 *     `X-Clawnify-*` headers, so an app never hand-parses them (see identity.ts).
 *
 * The point: a new always-required concern is added HERE once and every app
 * inherits it on the next rebuild — instead of a line each agent must remember
 * to write (and a build gate to enforce) in every app.
 */
import { OpenAPIHono, mountDiscovery, type DiscoveryOptions } from "@clawnify/routes";
import { initDB } from "@clawnify/db";
import type { Env } from "hono";

// One routing import for app authors: everything needed to declare routes and
// build the app comes from @clawnify/app. These are re-exports of the same
// @hono/zod-openapi primitives @clawnify/routes exposes — never reimplemented —
// so route creation, discovery, and construction all live behind one import.
export {
  OpenAPIHono,
  createRoute,
  z,
  mountDiscovery,
  describeRoutes,
} from "@clawnify/routes";
export type { DiscoveryOptions, DiscoverableApp } from "@clawnify/routes";

// Identity of the caller, read from the platform-injected headers. Apps never
// authenticate anyone themselves — see identity.ts.
export { user, orgId, caller } from "./identity";
export type { AppUser, Caller, RequestLike } from "./identity";

export interface CreateAppOptions extends DiscoveryOptions {
  /**
   * Wire the per-request database middleware (`initDB(c.env)` on `*`). Default
   * true — every Clawnify app has a D1 / Storage binding. Set false only for the
   * rare app with no database.
   */
  db?: boolean;
  /**
   * Mount GET /api/openapi.json + GET /llms.txt discovery. Default true. Set
   * false only if the app deliberately opts out of API discovery.
   */
  discovery?: boolean;
}

/**
 * Create a fully-wired Clawnify app.
 *
 * `E` is your Hono env — `{ Bindings: { DB: D1Database, ... } }` — pass it so
 * route handlers get a typed `c.env`. Everything after this call is your app's
 * own routes and business logic:
 *
 *   const app = createApp<Env>({ title: "CRM App", version: "1.0.0" });
 *   app.openapi(route, handler);
 *   export default app;
 */
export function createApp<E extends Env = Env>(
  opts: CreateAppOptions = {},
): OpenAPIHono<E> {
  const app = new OpenAPIHono<E>();

  if (opts.db !== false) {
    app.use("*", async (c, next) => {
      // @clawnify/db reads the DB (D1) or Storage binding off the env and caches
      // the Drizzle client for this request. Safe to call on every request.
      initDB(c.env as unknown as Parameters<typeof initDB>[0]);
      await next();
    });
  }

  if (opts.discovery !== false) {
    mountDiscovery(app, opts);
  }

  return app;
}
