/**
 * Identity — who is calling this app.
 *
 * The platform authenticates the caller at the perimeter (app-router, the
 * app-supervisor preview tier, or the /v1/apps/:id/proxy API) and injects a
 * *fresh* set of `X-Clawnify-*` headers. Any client-supplied `X-Clawnify-*` is
 * stripped first, so these headers cannot be spoofed and an app can trust them
 * directly.
 *
 * Apps therefore never authenticate anyone themselves: never read
 * `Authorization`, never parse a cookie, never verify a JWT. Read these
 * helpers instead.
 *
 *   import { user, orgId, caller } from "@clawnify/app";
 *
 *   app.openapi(route, (c) => {
 *     const u = user(c);                       // null when the caller isn't a person
 *     return c.json({ hello: u?.name ?? "there", org: orgId(c) });
 *   });
 */

/**
 * Minimal shape this module needs — Hono's `Context` satisfies it structurally,
 * so `user(c)` works in any handler regardless of the app's Env generics.
 */
export interface RequestLike {
  req: { header(name: string): string | undefined };
}

/**
 * What kind of principal is calling.
 *
 * Only `user`, `api` and `agent` carry a human identity; the rest are machine
 * or anonymous callers, for which `user()` returns null.
 *
 * | Value           | Who                                                        |
 * |-----------------|------------------------------------------------------------|
 * | `user`          | a signed-in person in a browser                             |
 * | `api`           | a person via the REST API / CLI / MCP (their own token)     |
 * | `agent`         | the org's OpenClaw agent calling the app's API              |
 * | `agent-browser` | the agent driving a real browser on its VPS                 |
 * | `public`        | an unauthenticated visitor on a declared public route       |
 * | `bypass`        | platform-internal fetch (build/screenshot)                  |
 * | `system`        | the build pipeline                                          |
 * | `app`           | another app in the same org (or a headless org-token caller)|
 */
export type Caller =
  | "user"
  | "api"
  | "agent"
  | "agent-browser"
  | "public"
  | "bypass"
  | "system"
  | "app";

const CALLERS = new Set<Caller>([
  "user",
  "api",
  "agent",
  "agent-browser",
  "public",
  "bypass",
  "system",
  "app",
]);

/** The signed-in person behind a request. */
export interface AppUser {
  /** Supabase user id — the stable key to store on rows (`created_by`). */
  id: string;
  email: string | null;
  /** Display name, e.g. "Ada Lovelace". Null if the account has no name set. */
  name: string | null;
  /** Profile picture URL (https). Null if the account has no avatar. */
  avatarUrl: string | null;
  /**
   * Best-effort split of `name` — a HEURISTIC, not platform data.
   *
   * The platform stores one `full_name`; there is no real given/family split
   * behind it. This takes the first whitespace-separated token, which is wrong
   * for many names (mononyms, multi-word given names, family-name-first
   * cultures). Use it for a friendly greeting ("Hi, Ada"), never as a stored
   * field or a record of someone's legal name — persist `name` instead.
   */
  firstName: string | null;
  /** Remainder of `name` after the first token. Same heuristic caveat. */
  lastName: string | null;
}

function read(c: RequestLike, name: string): string | null {
  const v = c.req.header(name);
  if (v === undefined) return null;
  const trimmed = v.trim();
  return trimmed === "" ? null : trimmed;
}

function splitName(name: string | null): Pick<AppUser, "firstName" | "lastName"> {
  if (!name) return { firstName: null, lastName: null };
  const parts = name.split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: null, lastName: null };
  if (parts.length === 1) return { firstName: parts[0], lastName: null };
  return { firstName: parts[0], lastName: parts.slice(1).join(" ") };
}

/**
 * What kind of principal is calling.
 *
 * Defaults to `"public"` — the least-privileged value — when the header is
 * missing or unrecognised, which happens when the app is reached outside the
 * platform perimeter (local `pnpm dev`). Gate privileged behaviour on an
 * explicit check (`caller(c) === "user"`), never on "not public".
 */
export function caller(c: RequestLike): Caller {
  const v = read(c, "X-Clawnify-Caller");
  return v && CALLERS.has(v as Caller) ? (v as Caller) : "public";
}

/**
 * The organization this request belongs to — the tenant key. Scope every query
 * by it.
 *
 * Present for `user`, `api`, `agent` and `app` callers. **Null** for
 * `agent-browser`, `public` and `bypass` — those reach the app through the
 * perimeter without an org-scoped identity — and null outside the platform.
 *
 * Treat null as "no access", never as a wildcard: a query filtered on a null
 * org must return nothing, not everything.
 */
export function orgId(c: RequestLike): string | null {
  return read(c, "X-Clawnify-Org-Id");
}

/**
 * The person behind this request, or `null` when the caller isn't one.
 *
 * Null for `agent-browser`, `public`, `bypass`, `system` and `app` — five of
 * the eight caller types — so always handle the null case rather than assuming
 * a user is present:
 *
 *   const u = user(c);
 *   const label = u ? u.name ?? u.email : "Automated";
 */
export function user(c: RequestLike): AppUser | null {
  const id = read(c, "X-Clawnify-User-Id");
  if (!id) return null;

  const name = read(c, "X-Clawnify-User-Name");
  return {
    id,
    email: read(c, "X-Clawnify-User-Email"),
    name,
    avatarUrl: read(c, "X-Clawnify-User-Avatar"),
    ...splitName(name),
  };
}
