/**
 * @clawnify/routes — one-line, reliable API discovery for Clawnify apps.
 *
 * `mountDiscovery(app)` serves two routes on your Hono / OpenAPIHono app:
 *   • GET /api/openapi.json — the OpenAPI 3.1 document
 *   • GET /llms.txt         — the same, as agent-readable markdown
 * and makes `/api/*` 404s self-describing: the JSON error body lists the app's
 * real endpoints, so an agent that guessed a wrong route self-corrects in the
 * same round trip instead of dead-ending.
 *
 * Why a helper instead of two hand-written routes: it's the discovery contract
 * every Clawnify app is expected to expose, so agents (and the platform's
 * `describe → call` flow) can find endpoints without guessing. It's derived
 * from the app's *live routes*, so it can't drift:
 *   • If the app is an OpenAPIHono (routes declared with `createRoute`), the
 *     document carries full request/response schemas.
 *   • Any `/api/*` route the OpenAPI document doesn't cover (a plain `app.get`
 *     with no `createRoute`) is still listed — path + method — from the Hono
 *     route table, so the endpoint list is complete even when schemas aren't.
 *
 * Depends only on `@scalar/openapi-to-markdown` (the OpenAPI→markdown renderer
 * clawnify's own API already uses). `hono` is a peer; `@hono/zod-openapi` is
 * detected structurally, never imported, so plain-Hono apps work too.
 */
import type { Hono } from "hono";

// Re-export the routing primitives so a Clawnify app has ONE routing import:
//   import { OpenAPIHono, createRoute, z, mountDiscovery } from "@clawnify/routes";
// These are @hono/zod-openapi's own exports (a required peer) — we re-export,
// never reimplement, so route creation and discovery live behind one import and
// mountDiscovery can't be forgotten.
export { OpenAPIHono, createRoute, z } from "@hono/zod-openapi";

export interface DiscoveryOptions {
  /** OpenAPI `info.title`. Defaults to "App API". */
  title?: string;
  /** OpenAPI `info.version`. Defaults to "1.0.0". */
  version?: string;
  /** Optional OpenAPI `info.description`. */
  description?: string;
}

interface OpenApiDoc {
  openapi?: string;
  info?: unknown;
  paths?: Record<string, Record<string, unknown>>;
}

/**
 * Any Hono app — plain `Hono` or `OpenAPIHono<Env>`. Generics are `any` so both
 * are accepted without friction. We do NOT put `getOpenAPI31Document` in this
 * type: an OpenAPIHono's real method signature (`(config: OpenAPIObjectConfig)`)
 * isn't assignable to a loosely-typed optional property under strict function
 * checks, which would reject every OpenAPIHono at the call site. Instead we
 * detect it structurally at runtime (see `openApiDocFn`).
 */
export type DiscoverableApp = Hono<any, any, any>;

/** Structurally recover OpenAPIHono's doc generator without a type dependency. */
function openApiDocFn(app: DiscoverableApp): ((config: unknown) => OpenApiDoc) | undefined {
  const fn = (app as unknown as { getOpenAPI31Document?: unknown }).getOpenAPI31Document;
  return typeof fn === "function" ? (fn.bind(app) as (config: unknown) => OpenApiDoc) : undefined;
}

interface RouteRow {
  method: string;
  path: string;
}

const OWN_PATHS = new Set(["/api/openapi.json", "/llms.txt"]);

function docConfig(opts: DiscoveryOptions) {
  return {
    openapi: "3.1.0",
    info: {
      title: opts.title ?? "App API",
      version: opts.version ?? "1.0.0",
      ...(opts.description ? { description: opts.description } : {}),
    },
  };
}

/** Hono uses `:param`; OpenAPI uses `{param}`. */
function toOpenApiPath(path: string): string {
  return path.replace(/:([A-Za-z0-9_]+)/g, "{$1}");
}

/**
 * Deduped `/api/*` endpoints from the live Hono route table — excluding
 * middleware ("ALL") and our own discovery routes. This is the source of truth
 * for "what endpoints exist": it reflects every registered handler, whether or
 * not it was declared with `createRoute`.
 */
function apiRoutes(app: DiscoverableApp): RouteRow[] {
  const seen = new Set<string>();
  const out: RouteRow[] = [];
  const rows = (app.routes ?? []) as RouteRow[];
  for (const r of rows) {
    if (!r || typeof r.path !== "string" || typeof r.method !== "string") continue;
    if (r.method === "ALL") continue; // middleware / use(), not an endpoint
    if (!r.path.startsWith("/api")) continue;
    if (OWN_PATHS.has(r.path)) continue;
    const method = r.method.toUpperCase();
    const key = `${method} ${r.path}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ method, path: r.path });
  }
  return out;
}

/**
 * Best-effort OpenAPI document: the real one from `@hono/zod-openapi` if the
 * app is an OpenAPIHono, else a minimal document synthesized from the route
 * table (paths + methods, no schemas).
 */
function buildDoc(app: DiscoverableApp, opts: DiscoveryOptions): OpenApiDoc {
  const genDoc = openApiDocFn(app);
  if (genDoc) {
    try {
      return genDoc(docConfig(opts));
    } catch {
      // A schema-build error should never make discovery 500 — a partial
      // answer (the route table) beats none. Fall through.
    }
  }
  const paths: Record<string, Record<string, unknown>> = {};
  for (const r of apiRoutes(app)) {
    const p = toOpenApiPath(r.path);
    (paths[p] ??= {})[r.method.toLowerCase()] = {
      responses: { "200": { description: "OK" } },
    };
  }
  return { ...docConfig(opts), paths };
}

/**
 * Every endpoint as `{ method, path, summary? }` — OpenAPI-documented routes
 * first (with their summary), then route-table-only routes (path + method).
 * The same inventory llms.txt renders, as data.
 */
function endpointEntries(
  app: DiscoverableApp,
  doc: OpenApiDoc,
): Array<{ method: string; path: string; summary?: string }> {
  const out: Array<{ method: string; path: string; summary?: string }> = [];
  for (const [path, ops] of Object.entries(doc.paths ?? {})) {
    for (const [method, op] of Object.entries(ops)) {
      const o = op as { summary?: string; description?: string } | undefined;
      const note = o?.summary || o?.description;
      out.push({ method: method.toUpperCase(), path, ...(note ? { summary: note } : {}) });
    }
  }
  const documented = documentedSet(doc);
  for (const r of apiRoutes(app)) {
    if (!documented.has(`${r.method} ${toOpenApiPath(r.path)}`)) {
      out.push({ method: r.method, path: r.path });
    }
  }
  return out;
}

function documentedSet(doc: OpenApiDoc): Set<string> {
  const s = new Set<string>();
  for (const [p, ops] of Object.entries(doc.paths ?? {})) {
    for (const m of Object.keys(ops)) s.add(`${m.toUpperCase()} ${p}`);
  }
  return s;
}

/**
 * Structured endpoint list for build gates and platform tooling — the same
 * data `mountDiscovery` serves, without an HTTP request. `documented` is true
 * when the endpoint carries an OpenAPI schema (declared via `createRoute`),
 * false when it's only known from the route table.
 */
export function describeRoutes(
  app: DiscoverableApp,
  opts: DiscoveryOptions = {},
): {
  openapi: OpenApiDoc;
  endpoints: Array<{ method: string; path: string; documented: boolean }>;
} {
  const doc = buildDoc(app, opts);
  const documented = documentedSet(doc);
  const endpoints = apiRoutes(app).map((r) => ({
    method: r.method,
    path: r.path,
    documented: documented.has(`${r.method} ${toOpenApiPath(r.path)}`),
  }));
  return { openapi: doc, endpoints };
}

/**
 * Build the llms.txt index (llmstxt.org shape): an H1 title, a one-line summary,
 * an endpoint list (`METHOD /path — summary`), and a link to the full OpenAPI
 * spec. It's a lean *doorway* that points at the machine contract — NOT a full
 * dump of it (that's what /api/openapi.json is for). Generated from the same
 * live doc, so the app author never hand-writes it and it never drifts.
 */
function buildLlmsIndex(app: DiscoverableApp, opts: DiscoveryOptions): string {
  const doc = buildDoc(app, opts);
  const info = (doc.info ?? {}) as { title?: string; description?: string };
  const title = info.title || opts.title || "App API";

  const lines: string[] = [`# ${title}`];
  const summary = info.description || opts.description;
  if (summary) lines.push("", `> ${summary}`);

  // Documented routes carry their summary; plain routes with no createRoute
  // schema are still listed (path + method), so the inventory is complete
  // even when schemas aren't declared.
  const entries = endpointEntries(app, doc).map(
    (e) => `- \`${e.method} ${e.path}\`${e.summary ? ` — ${e.summary}` : ""}`,
  );
  if (entries.length) lines.push("", "## API", ...entries);

  lines.push("", "Full machine-readable spec: [/api/openapi.json](/api/openapi.json)");
  return lines.join("\n") + "\n";
}

/**
 * Mount `GET /api/openapi.json` + `GET /llms.txt` on the app, and register a
 * self-describing 404 for `/api/*`. Call once, just before `export default
 * app`. Static routes win over a `*` static/SPA catch-all in Hono's router
 * regardless of registration order, but calling this before the catch-all
 * keeps intent obvious. An app that registers its own `app.notFound()` after
 * this call overrides the 404 handler — normal Hono precedence.
 */
export function mountDiscovery(app: DiscoverableApp, opts: DiscoveryOptions = {}): void {
  app.get("/api/openapi.json", (c) => c.json(buildDoc(app, opts)));

  app.get("/llms.txt", (c) =>
    c.text(buildLlmsIndex(app, opts), 200, {
      "Content-Type": "text/markdown; charset=utf-8",
      "Cache-Control": "public, max-age=300",
    }),
  );

  // Self-describing /api/* 404s: an agent (MCP call_app_api, CLI proxy,
  // app-to-app) that guessed a wrong route or method learns the app's real
  // endpoints in the same round trip. Non-/api paths keep Hono's default 404 —
  // they're the SPA/asset tier (the preview supervisor falls back to R2 on
  // those, and only on those).
  app.notFound((c) => {
    if (!c.req.path.startsWith("/api")) return c.text("404 Not Found", 404);

    const body: Record<string, unknown> = {
      error: "not_found",
      message: `No route for ${c.req.method} ${c.req.path} on this app.`,
      hint: "GET /llms.txt lists every endpoint; GET /api/openapi.json has full request/response schemas.",
    };

    // Endpoint inventory only for platform-authenticated callers. The
    // X-Clawnify-Caller header is injected fresh by the perimeter (client
    // copies are stripped), so it's trustworthy; "public" is an unauthenticated
    // visitor on a declared public route, and a missing header means the app is
    // running outside the platform — both get the pointer, not the map.
    const caller = c.req.header("X-Clawnify-Caller");
    if (caller && caller !== "public") {
      body.endpoints = endpointEntries(app, buildDoc(app, opts));
    }

    return c.json(body, 404);
  });
}
